import math
from math import log, sqrt, exp, erf

def N(x): return 0.5*(1+erf(x/sqrt(2)))
def bs_delta(S,K,T,sigma,r=0.04, call=True, q=0.0):
    d1 = (log(S/K)+(r-q+0.5*sigma**2)*T)/(sigma*sqrt(T))
    if call: return N(d1)
    return N(d1)-1

S=100.0
print("Stock=$100. Deltas (per ~30d and ~90d, r=4%, no div)")
print(f"{'Strike':>8} {'%OTM':>6} {'typ':>5} {'sigma':>6} {'d30':>7} {'d90':>7}")
for K,label in [(105,'5% OTM'),(108,'8% OTM'),(110,'10% OTM'),(115,'15% OTM'),(95,'5% OTM'),(92,'8% OTM'),(90,'10% OTM'),(85,'15% OTM'),(80,'20% OTM')]:
    o_type = 'C' if K>S else 'P'
    for sig in (0.20,0.30):
        d30 = bs_delta(S,K,30/365,sig)
        d90 = bs_delta(S,K,90/365,sig)
        if o_type=='P': d30=-(-d30); 
        print(f"{K:>8} {label:>6} {o_type:>5} {sig:>6.2f} {d30:>7.3f} {d90:>7.3f}")
